   438  void Udp::UpdateChecksum(Message &aMessage, uint16_t aChecksum)
   439  {
   440      aChecksum = aMessage.UpdateChecksum(aChecksum, aMessage.GetOffset(), aMessage.GetLength() - aMessage.GetOffset());
   441
   442      if (aChecksum != 0xffff)
   443      {
   444          aChecksum = ~aChecksum;
   445      }
   446
   447      aChecksum = HostSwap16(aChecksum);
   448      aMessage.Write(aMessage.GetOffset() + UdpHeader::GetChecksumOffset(), sizeof(aChecksum), &aChecksum);
   449  }
